import{_ as t,o,c as r,ae as a}from"./chunks/framework.EHGTsUvI.js";const p=JSON.parse('{"title":"Bees","description":"","frontmatter":{"title":"Bees"},"headers":[],"relativePath":"Main/Main/GeneralKnowledge/Animals/bees.md","filePath":"Main/Main/GeneralKnowledge/Animals/bees.md"}'),n={name:"Main/Main/GeneralKnowledge/Animals/bees.md"};function i(s,e,d,l,c,h){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="bees" tabindex="-1">Bees <a class="header-anchor" href="#bees" aria-label="Permalink to &quot;Bees&quot;">​</a></h1><p>Bees are a livestock animal that produce <strong>Honey Frames</strong>. Honey Frames are processed into Honey Barrels using the <strong>Honey Factory</strong>.</p><p>Honey can either be sold directly or used with Oats in the <strong>Honey Oatmeal Factory</strong>.</p><h2 id="how-to-obtain" tabindex="-1">How to Obtain <a class="header-anchor" href="#how-to-obtain" aria-label="Permalink to &quot;How to Obtain&quot;">​</a></h2><p>Bees are purchased from the <strong>AnimalCo Store</strong> in <strong>Bee Boxes</strong>.</p><p>Each Bee Box contains <strong>1 Bee</strong>.</p><p>To obtain a bee:</p><ol><li>Visit the AnimalCo Store.</li><li>Purchase a Bee Box.</li><li>Take the Bee Box back to your farm.</li><li>Place the Bee Box into an available Hive.</li><li>The bee will begin producing Honey Frames.</li></ol><h2 id="purchase-price" tabindex="-1">Purchase Price <a class="header-anchor" href="#purchase-price" aria-label="Permalink to &quot;Purchase Price&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Information</th><th>Details</th></tr></thead><tbody><tr><td>Bee Box</td><td>15,000 Coins</td></tr><tr><td>Bees per Box</td><td>1 Bee</td></tr></tbody></table><p>Each Bee Box costs <strong>15,000 Coins</strong> and contains one Bee.</p><h2 id="housing-requirements" tabindex="-1">Housing Requirements <a class="header-anchor" href="#housing-requirements" aria-label="Permalink to &quot;Housing Requirements&quot;">​</a></h2><p>Bees must be placed inside a <strong>Hive</strong>.</p><table tabindex="0"><thead><tr><th>Requirement</th><th>Details</th></tr></thead><tbody><tr><td>Housing</td><td>Hive</td></tr><tr><td>Maximum Bees</td><td>6 Bees per Hive</td></tr><tr><td>Food</td><td>Not Required</td></tr><tr><td>Cleaning</td><td>Required</td></tr></tbody></table><p>A Hive can hold up to <strong>6 Bees</strong> by default.</p><p>Hive capacity can be increased through certain upgrades and tasks.</p><h2 id="food-requirements" tabindex="-1">Food Requirements <a class="header-anchor" href="#food-requirements" aria-label="Permalink to &quot;Food Requirements&quot;">​</a></h2><p>Bees <strong>do not require food</strong>.</p><p>Unlike chickens, cows and sheep, bees do not need an Animal Food feeder.</p><p>Instead, Bees remain inside their Hive and produce Honey Frames automatically.</p><blockquote><p><strong>Note:</strong> Hives still need to be cleaned regularly.</p></blockquote><h2 id="products-produced" tabindex="-1">Products Produced <a class="header-anchor" href="#products-produced" aria-label="Permalink to &quot;Products Produced&quot;">​</a></h2><p>Bees produce <strong>Honey Frames</strong>.</p><p>Honey Frames are processed using the <strong>Honey Factory</strong> to produce Honey Barrels.</p><table tabindex="0"><thead><tr><th>Product</th><th>Details</th></tr></thead><tbody><tr><td>Honey Frame</td><td>Produced by Bees</td></tr><tr><td>Honey Barrel</td><td>Produced from Honey Frames</td></tr><tr><td>Honey Oatmeal</td><td>Produced using Honey and Oats</td></tr></tbody></table><p>Honey can be used in two main ways:</p><ul><li>Sold for Coins</li><li>Combined with Oats in the Honey Oatmeal Factory</li></ul><h2 id="production-time" tabindex="-1">Production Time <a class="header-anchor" href="#production-time" aria-label="Permalink to &quot;Production Time&quot;">​</a></h2><p>Bees take approximately <strong>15 minutes</strong> to produce Honey.</p><p>Each Bee produces <strong>4 Honey Frames</strong> during its production cycle.</p><table tabindex="0"><thead><tr><th>Information</th><th>Details</th></tr></thead><tbody><tr><td>Production Time</td><td>15 minutes</td></tr><tr><td>Honey Frames per Bee</td><td>4</td></tr><tr><td>Bees per Hive</td><td>Up to 6</td></tr></tbody></table><p>A full Hive containing 6 Bees can therefore produce up to <strong>24 Honey Frames</strong> per production cycle.</p><h2 id="selling-information" tabindex="-1">Selling Information <a class="header-anchor" href="#selling-information" aria-label="Permalink to &quot;Selling Information&quot;">​</a></h2><p>Honey is processed through the <strong>Honey Factory</strong> before being sold.</p><p>The Honey Factory converts Honey Frames into <strong>Honey Barrels</strong>.</p><p>Honey Barrels can then be:</p><ul><li>Sold for Coins</li><li>Used to produce Honey Oatmeal</li></ul><blockquote><p><strong>Note:</strong> The current selling value of Honey can change and should be checked in-game before calculating expected profits.</p></blockquote><h2 id="required-license" tabindex="-1">Required License <a class="header-anchor" href="#required-license" aria-label="Permalink to &quot;Required License&quot;">​</a></h2><table tabindex="0"><thead><tr><th>License</th><th>Required</th></tr></thead><tbody><tr><td>Bee License</td><td>Yes</td></tr></tbody></table><p>The <strong>Bee License</strong> is required to use the Bee system.</p><p>The Bee system is unlocked through the <strong>Animals Goals</strong> progression.</p><h2 id="other-useful-information" tabindex="-1">Other Useful Information <a class="header-anchor" href="#other-useful-information" aria-label="Permalink to &quot;Other Useful Information&quot;">​</a></h2><ul><li>Bee Boxes cost <strong>15,000 Coins</strong> each.</li><li>Each Bee Box contains <strong>1 Bee</strong>.</li><li>Bees do not require Animal Food.</li><li>Bees are housed inside <strong>Hives</strong>.</li><li>Hives can hold up to <strong>6 Bees</strong> before upgrades.</li><li>Bees produce <strong>4 Honey Frames every 15 minutes</strong>.</li><li>A full Hive of 6 Bees can produce up to <strong>24 Honey Frames per cycle</strong>.</li><li>Honey Frames are processed in the <strong>Honey Factory</strong>.</li><li>Honey Barrels can be sold directly.</li><li>Honey can also be combined with <strong>Oats</strong> to produce Honey Oatmeal.</li><li>Hives need to be cleaned regularly.</li><li>Bees are particularly useful for players who want to run a Honey or Honey Oatmeal production chain.</li></ul>',44)])])}const g=t(n,[["render",i]]);export{p as __pageData,g as default};
